code.cpp:
class Solution {
public:
    int maxSum(vector<int>& nums, int k) {
        const long long MOD = 1000000007;
        int cnt[31] = {0};
        for (int x : nums) {
            for (int b = 0; b < 31; b++) {
                if (x & (1 << b)) cnt[b]++;
            }
        }
        long long ans = 0;
        for (int i = 0; i < k; i++) {
            long long num = 0;
            for (int b = 0; b < 31; b++) {
                if (cnt[b] > i) {
                    num |= (1LL << b);
                }
            }
            long long sq = (num % MOD) * (num % MOD) % MOD;
            ans = (ans + sq) % MOD;
        }
        return (int)ans;
    }
};
